INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0873', 'کرانچ معکوس سیم‌کش', 'Cable reverse crunch', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'خم‌کننده ران', '۱. یک کابل را به قرقره پایین وصل کنید و به پشت روی تشک دراز بکشید.
۲. کابل را با دو دست بگیرید و دست‌ها را صاف به سمت سقف بالا ببرید.
۳. زانوها را خم کنید و پاها را بالا بیاورید تا ران‌ها به سینه نزدیک شوند.
۴. بالاتنه را ثابت نگه دارید و لگن را به سمت سینه جمع کنید و باسن را از تشک بلند کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس لگن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0873.gif', 'abs', 'hip-flexors', '1. Attach a cable to a low pulley and lie down facing up on a mat.
2. Hold the cable with both hands and extend your arms straight up towards the ceiling.
3. Bend your knees and lift your legs up, bringing your thighs towards your chest.
4. While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.
5. Pause for a moment at the top, then slowly lower your hips back down to the starting position.
6. Repeat for the desired number of repetitions.', '0873') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0206', 'جلو بازو برعکس سیم‌کش', 'Cable reverse curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. یک میله صاف را به قرقره پایین سیم‌کش وصل کنید.
۲. رو به دستگاه بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۳. میله را از زیر و به اندازه عرض شانه بگیرید.
۴. در طول تمرین آرنج‌ها را نزدیک پهلوها و بازوها را ثابت نگه دارید.
۵. با بازدم میله را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۶. لحظه‌ای در بالا مکث کنید و جلو بازو را منقبض کنید.
۷. با دم، میله را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0206.gif', 'biceps', 'forearm', '1. Attach a straight bar to a low pulley cable machine.
2. Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.
3. Grasp the bar with an underhand grip, hands shoulder-width apart.
4. Keep your elbows close to your sides and your upper arms stationary throughout the exercise.
5. Exhale and curl the bar up towards your shoulders, contracting your biceps.
6. Pause for a moment at the top, squeezing your biceps.
7. Inhale and slowly lower the bar back to the starting position, fully extending your arms.
8. Repeat for the desired number of repetitions.', '0206') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2406', 'پشت بازو دست‌برعکس با میله SZ و آرم‌بلستر سیم‌کش', 'Cable reverse grip triceps pushdown (sz-bar) (with arm blaster)', 'arms', 'بازو', 'cable', 'سیم‌کش', 'پشت بازو', 'ساعد', '۱. یک میله صاف را در بالاترین ارتفاع به سیم‌کش وصل کنید.
۲. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. میله را از زیر با کف دست رو به بالا و دست‌ها به اندازه عرض شانه بگیرید.
۴. در طول تمرین آرنج‌ها را نزدیک پهلوها و بازوها را ثابت نگه دارید.
۵. پشت بازو را درگیر کنید و میله را آرام پایین فشار دهید تا دست‌ها کاملاً صاف شوند.
۶. لحظه‌ای در پایین مکث کنید، سپس میله را آرام به وضعیت شروع برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2406.gif', 'triceps', 'forearm', '1. Attach a straight bar to the cable machine at the highest setting.
2. Stand facing the cable machine with your feet shoulder-width apart.
3. Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.
4. Keep your elbows close to your sides and your upper arms stationary throughout the exercise.
5. Engage your triceps and slowly push the bar down until your arms are fully extended.
6. Pause for a moment at the bottom, then slowly return the bar to the starting position.
7. Repeat for the desired number of repetitions.', '2406') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1413', 'جلو بازو برعکس تک‌دست سیم‌کش', 'Cable reverse one arm curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره کابل را با کف دست رو به پایین بگیرید.
۳. آرنج را نزدیک پهلو نگه دارید و ساعد را آرام به سمت شانه بالا بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس ساعد را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1413.gif', 'biceps', 'forearm', '1. Stand facing a cable machine with your feet shoulder-width apart.
2. Grasp the cable handle with an underhand grip, palm facing down.
3. Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.
4. Pause for a moment at the top, then slowly lower your forearm back down to the starting position.
5. Repeat for the desired number of repetitions.', '1413') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0209', 'جلو بازو لاری برعکس سیم‌کش', 'Cable reverse preacher curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. سیم‌کش را طوری تنظیم کنید که پد لاری در ارتفاع سینه باشد.
۲. روی نیمکت لاری بنشینید و بازوها را روی پد بگذارید، کف دست رو به پایین و آرنج‌ها کاملاً صاف.
۳. دستگیره‌های کابل را از زیر و به اندازه عرض شانه بگیرید.
۴. بازوها را ثابت نگه دارید و با بازدم دستگیره‌ها را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۵. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۶. با دم، دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید و آرنج‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0209.gif', 'biceps', 'forearm', '1. Adjust the cable machine so that the preacher curl pad is at chest height.
2. Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.
3. Grab the cable handles with an underhand grip, shoulder-width apart.
4. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.
5. Pause for a moment at the top of the movement, squeezing your biceps.
6. Inhale and slowly lower the handles back to the starting position, fully extending your elbows.
7. Repeat for the desired number of repetitions.', '0209') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0210', 'مچ دست معکوس سیم‌کش', 'Cable reverse wrist curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'ساعد', 'ساعد، مچ دست', '۱. یک کابل را به قرقره پایین وصل کنید و رو به سیم‌کش روی نیمکت بنشینید.
۲. دستگیره کابل را از رو با کف دست رو به پایین بگیرید.
۳. ساعدها را روی ران‌ها بگذارید و مچ‌ها از لبه آویزان باشند.
۴. ساعدها را ثابت نگه دارید و با بازدم، مچ‌ها را تا جای ممکن به سمت بالا خم کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس با دم مچ‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0210.gif', 'forearm', '', '1. Attach a cable to a low pulley and sit on a bench facing the cable machine.
2. Grasp the cable handle with an overhand grip, palms facing down.
3. Rest your forearms on your thighs, with your wrists hanging off the edge.
4. Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.
5. Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.
6. Repeat for the desired number of repetitions.', '0210') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0207', 'پشت بازو دست‌برعکس سیم‌کش', 'Cable reverse-grip pushdown', 'arms', 'بازو', 'cable', 'سیم‌کش', 'پشت بازو', 'ساعد', '۱. یک میله صاف را به قرقره بالای سیم‌کش وصل کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. میله را از زیر با کف دست رو به بالا و دست‌ها به اندازه عرض شانه بگیرید.
۴. در طول تمرین آرنج‌ها را نزدیک پهلوها و بازوها را ثابت نگه دارید.
۵. با کمک پشت بازو میله را پایین فشار دهید تا دست‌ها کاملاً صاف و پشت بازو منقبض شود.
۶. لحظه‌ای مکث کنید، سپس میله را آرام به وضعیت شروع برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0207.gif', 'triceps', 'forearm', '1. Attach a straight bar to a high pulley cable machine.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.
4. Keep your elbows close to your sides and your upper arms stationary throughout the exercise.
5. Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.
6. Pause for a moment, then slowly return the bar to the starting position.
7. Repeat for the desired number of repetitions.', '0207') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0208', 'قایقی بالا نشسته کمر صاف دست‌برعکس سیم‌کش', 'Cable reverse-grip straight back seated high row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، ساعد', '۱. رو به سیم‌کش روی صندلی بنشینید و کف پاها را روی زمین بگذارید.
۲. دستگیره کابل را از زیر با کف دست رو به بالا و دست‌ها به اندازه عرض شانه بگیرید.
۳. کمر را صاف نگه دارید و کمی از لگن به جلو متمایل شوید.
۴. با جمع کردن کتف‌ها و انقباض عضلات پشت، کابل را به سمت تنه بکشید.
۵. لحظه‌ای در اوج انقباض مکث کنید، سپس کابل را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0208.gif', 'upper-back', 'biceps,forearm', '1. Sit on the seat facing the cable machine with your feet flat on the floor.
2. Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.
3. Keep your back straight and lean slightly forward from your hips.
4. Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.
5. Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.
6. Repeat for the desired number of repetitions.', '0208') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1320', 'قایقی نشسته کراس‌اور با طناب سیم‌کش', 'Cable rope crossover seated row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، ساعد', '۱. روی دستگاه قایقی بنشینید، کف پاها روی جاپایی و زانوها کمی خم باشد.
۲. طناب‌های کابل را از رو با کف دست‌های رو به هم بگیرید.
۳. کمی به عقب متمایل شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۴. طناب‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس کشش را آرام رها کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1320.gif', 'upper-back', 'biceps,forearm', '1. Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.
2. Grasp the cable ropes with an overhand grip, palms facing each other.
3. Lean back slightly, keeping your back straight and your core engaged.
4. Pull the cable ropes towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.
6. Repeat for the desired number of repetitions.', '1320') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1321', 'قایقی نشسته بالا با طناب سیم‌کش', 'Cable rope elevated seated row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، ساعد', '۱. رو به سیم‌کش روی صندلی بلند بنشینید.
۲. دستگیره‌های طناب را از رو با کف دست‌های رو به هم بگیرید.
۳. کمر را صاف نگه دارید و کمی به عقب متمایل شوید و زانوها را کمی خم نگه دارید.
۴. با جمع کردن کتف‌ها و انقباض عضلات پشت، کابل را به سمت بدن بکشید.
۵. لحظه‌ای در حالت انقباض کامل مکث کنید.
۶. کشش را آرام رها کنید و دست‌ها را به وضعیت شروع صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1321.gif', 'upper-back', 'biceps,forearm', '1. Sit on the elevated seat facing the cable machine.
2. Grab the cable rope handles with an overhand grip, palms facing each other.
3. Keep your back straight and lean slightly back, maintaining a slight bend in your knees.
4. Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.
5. Pause for a moment at the fully contracted position.
6. Slowly release the tension and extend your arms back to the starting position.
7. Repeat for the desired number of repetitions.', '1321') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1322', 'زیربغل روی نیمکت شیب‌دار با طناب سیم‌کش', 'Cable rope extension incline bench row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. نیمکت شیب‌دار را روی ۴۵ درجه تنظیم کنید و از قرقره پایین سیم‌کش استفاده کنید.
۲. یک طناب را به سیم‌کش وصل کنید و رو به دستگاه روی نیمکت شیب‌دار بنشینید.
۳. طناب را از رو بگیرید و با کمر صاف به جلو متمایل شوید.
۴. دست‌ها را کاملاً باز کنید و طناب را به سمت بالای سینه بکشید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. در انتهای حرکت کتف‌ها را به هم فشار دهید.
۶. کشش را آرام رها کنید و به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1322.gif', 'upper-back', 'biceps,deltoids', '1. Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.
2. Attach a rope handle to the cable machine and sit on the incline bench facing the machine.
3. Grab the rope handle with an overhand grip and lean forward, keeping your back straight.
4. Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.
5. Squeeze your shoulder blades together at the end of the movement.
6. Slowly release the tension and return to the starting position.
7. Repeat for the desired number of repetitions.', '1322') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1639', 'جلو بازو چکشی لاری با طناب سیم‌کش', 'Cable rope hammer preacher curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. یک طناب را به قرقره پایین سیم‌کش وصل کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. طناب را با گرفتن خنثی (کف دست‌ها رو به هم) بگیرید.
۴. بازوها را روی پد نیمکت لاری قرار دهید و آرنج‌ها را کمی خم نگه دارید.
۵. بازوها را ثابت نگه دارید و با بازدم طناب را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۶. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۷. با دم، طناب را آرام به وضعیت شروع پایین بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1639.gif', 'biceps', 'forearm', '1. Attach a rope attachment to a low pulley cable machine.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the rope with a neutral grip (palms facing each other).
4. Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.
5. Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.
6. Hold the contracted position for a brief pause as you squeeze your biceps.
7. Inhale and slowly lower the rope back to the starting position.
8. Repeat for the desired number of repetitions.', '1639') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1724', 'پشت بازو بالای سر از قرقره بالا با طناب سیم‌کش', 'Cable rope high pulley overhead tricep extension', 'arms', 'بازو', 'cable', 'سیم‌کش', 'پشت بازو', 'شانه‌ها', '۱. یک طناب را به قرقره بالا وصل کنید و وزنه را مناسب تنظیم کنید.
۲. پشت به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. طناب را با دو دست و کف دست رو به پایین بگیرید و دست‌ها را بالای سر ببرید.
۴. بازوها را نزدیک سر و عمود بر زمین نگه دارید.
۵. با خم کردن آرنج‌ها طناب را آرام پشت سر پایین ببرید.
۶. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1724.gif', 'triceps', 'deltoids', '1. Attach a rope to a high pulley and adjust the weight accordingly.
2. Stand facing away from the pulley machine with your feet shoulder-width apart.
3. Grasp the rope with both hands, palms facing down, and bring your hands above your head.
4. Keep your upper arms close to your head and perpendicular to the floor.
5. Slowly lower the rope behind your head by bending your elbows.
6. Pause for a moment, then extend your arms back to the starting position.
7. Repeat for the desired number of repetitions.', '1724') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1725', 'پشت بازو روی نیمکت شیب‌دار با طناب سیم‌کش', 'Cable rope incline tricep extension', 'arms', 'بازو', 'cable', 'سیم‌کش', 'پشت بازو', 'شانه‌ها', '۱. یک طناب را به قرقره بالا وصل کنید و نیمکت شیب‌دار را روی زاویه مناسب تنظیم کنید.
۲. پشت به قرقره بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. طناب را از رو بگیرید و دست‌ها را صاف بالای سر ببرید.
۴. در طول تمرین آرنج‌ها را نزدیک سر و بازوها را ثابت نگه دارید.
۵. با خم کردن آرنج‌ها طناب را پشت سر پایین ببرید تا ساعدها به جلو بازو برسند.
۶. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1725.gif', 'triceps', 'deltoids', '1. Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.
2. Stand facing away from the pulley with your feet shoulder-width apart.
3. Grasp the rope with an overhand grip and extend your arms straight overhead.
4. Keep your elbows close to your head and your upper arms stationary throughout the exercise.
5. Lower the rope behind your head by bending your elbows until your forearms touch your biceps.
6. Pause for a moment, then extend your arms back to the starting position.
7. Repeat for the desired number of repetitions.', '1725') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1726', 'پشت بازو خوابیده روی زمین با طناب سیم‌کش', 'Cable rope lying on floor tricep extension', 'arms', 'بازو', 'cable', 'سیم‌کش', 'پشت بازو', 'شانه‌ها', '۱. یک طناب را به سیم‌کش وصل کنید و آن را در پایین‌ترین ارتفاع قرار دهید.
۲. به پشت روی زمین دراز بکشید، سر رو به سیم‌کش باشد.
۳. طناب را با دو دست و کف دست‌های رو به هم بگیرید و دست‌ها را صاف به سمت سقف بالا ببرید.
۴. بازوها را ثابت نگه دارید و با خم کردن آرنج‌ها طناب را آرام به سمت پیشانی پایین بیاورید.
۵. لحظه‌ای مکث کنید، سپس دست‌ها را به وضعیت شروع صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1726.gif', 'triceps', 'deltoids', '1. Attach a rope to a cable machine and set it to the lowest position.
2. Lie on the floor facing up, with your head towards the cable machine.
3. Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.
4. Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.
5. Pause for a moment, then extend your arms back up to the starting position.
6. Repeat for the desired number of repetitions.', '1726') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1640', 'جلو بازو چکشی لاری تک‌دست با طناب سیم‌کش', 'Cable rope one arm hammer preacher curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. یک طناب را به قرقره پایین سیم‌کش وصل کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره طناب را از زیر با کف دست رو به بالا بگیرید.
۴. بازو را روی پد نیمکت لاری قرار دهید و آرنج را کمی خم نگه دارید.
۵. در طول تمرین کمر را صاف و میان‌تنه را درگیر نگه دارید.
۶. دستگیره طناب را آرام به سمت شانه بالا بیاورید و بازو را ثابت نگه دارید.
۷. در اوج حرکت جلو بازو را منقبض کنید، سپس دستگیره را آرام به وضعیت شروع پایین بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1640.gif', 'biceps', 'forearm', '1. Attach a rope handle to a low pulley cable machine.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the rope handle with an underhand grip, palms facing up.
4. Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.
5. Keep your back straight and your core engaged throughout the exercise.
6. Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.
7. Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.
8. Repeat for the desired number of repetitions, then switch arms.', '1640') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1323', 'قایقی نشسته با طناب سیم‌کش', 'Cable rope seated row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، ساعد', '۱. روی دستگاه قایقی بنشینید، کف پاها روی جاپایی و زانوها کمی خم باشد.
۲. طناب‌های کابل را از رو با کف دست‌های رو به هم بگیرید.
۳. کمر را صاف نگه دارید و کمی به جلو متمایل شوید و آرنج‌ها را کمی خم نگه دارید.
۴. طناب‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس کشش را آرام رها کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1323.gif', 'upper-back', 'biceps,forearm', '1. Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.
2. Grasp the cable ropes with an overhand grip, palms facing each other.
3. Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.
4. Pull the cable ropes towards your body, squeezing your shoulder blades together.
5. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.
6. Repeat for the desired number of repetitions.', '1323') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0211', 'چرخش روسی سیم‌کش (روی توپ تعادلی)', 'Cable russian twists (on stability ball)', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها، پایین کمر', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. دستگیره سیم‌کش را با دو دست بگیرید و دست‌ها را صاف جلوی بدن دراز کنید.
۳. کمی به عقب متمایل شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۴. تنه را به راست بچرخانید و دستگیره را به سمت لگن راست ببرید.
۵. لحظه‌ای مکث کنید، سپس تنه را به چپ بچرخانید و دستگیره را به سمت لگن چپ ببرید.
۶. به تعداد تکرار دلخواه، چرخش‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0211.gif', 'abs', 'obliques,lower-back', '1. Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Hold the cable handle with both hands and extend your arms straight out in front of you.
3. Lean back slightly while keeping your back straight and your core engaged.
4. Twist your torso to the right, bringing the cable handle towards your right hip.
5. Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.
6. Continue alternating twists for the desired number of repetitions.', '0211') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2144', 'پرس سینه نشسته سیم‌کش', 'Cable seated chest press', 'chest', 'سینه', 'cable', 'سیم‌کش', 'سینه', 'شانه‌ها، پشت بازو', '۱. ارتفاع صندلی و دستگیره‌ها را در وضعیت مناسب تنظیم کنید.
۲. روی نیمکت با کمر صاف بنشینید و کف پاها را روی زمین بگذارید.
۳. دستگیره‌ها را از رو در ارتفاع شانه بگیرید.
۴. دستگیره‌ها را به جلو و دور از بدن هل دهید و دست‌ها را کاملاً صاف کنید.
۵. لحظه‌ای مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2144.gif', 'chest', 'deltoids,triceps', '1. Adjust the seat height and cable handles to a comfortable position.
2. Sit on the bench with your back straight and feet flat on the floor.
3. Grasp the cable handles with an overhand grip at shoulder height.
4. Push the handles forward and away from your body, extending your arms fully.
5. Pause for a moment, then slowly bring the handles back to the starting position.
6. Repeat for the desired number of repetitions.', '2144') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0212', 'کرانچ نشسته سیم‌کش', 'Cable seated crunch', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها', '۱. جلوی سیم‌کش بنشینید، کف پاها روی زمین و زانوها خم باشد.
۲. دستگیره را با دو دست بگیرید و پشت سر قرار دهید.
۳. شکم را درگیر کنید و بالاتنه را آرام به جلو خم کنید و سینه را به سمت زانوها ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0212.gif', 'abs', 'obliques', '1. Sit on a cable machine with your feet flat on the ground and your knees bent.
2. Hold the cable handle with both hands and position it behind your head.
3. Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.
4. Pause for a moment at the top, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '0212') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1641', 'جلو بازو نشسته سیم‌کش', 'Cable seated curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. جلوی سیم‌کش بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. دستگیره کابل را از زیر با کف دست رو به بالا و دست‌های کاملاً صاف بگیرید.
۳. بازوها را ثابت نگه دارید و با بازدم دستگیره را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۴. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، دستگیره را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1641.gif', 'biceps', 'forearm', '1. Sit on a cable machine with your feet flat on the ground and your back straight.
2. Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.
3. Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.
4. Pause for a moment at the top of the movement, squeezing your biceps.
5. Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '1641') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0213', 'قایقی بالا نشسته سیم‌کش (دستگیره V)', 'Cable seated high row (v-bar)', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. جلوی سیم‌کش بنشینید، کف پاها روی زمین و زانوها کمی خم باشد.
۲. دستگیره V را با کف دست‌های رو به هم و به اندازه عرض شانه بگیرید.
۳. کمر را صاف نگه دارید و کمی از لگن به جلو متمایل شوید.
۴. با جمع کردن کتف‌ها و انقباض عضلات پشت، دستگیره V را به سمت تنه بکشید.
۵. لحظه‌ای در اوج انقباض مکث کنید، سپس کشش را آرام رها کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0213.gif', 'upper-back', 'biceps,deltoids', '1. Sit on the cable machine with your feet flat on the floor and your knees slightly bent.
2. Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.
3. Keep your back straight and lean slightly forward from the hips.
4. Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.
5. Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.
6. Repeat for the desired number of repetitions.', '0213') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0214', 'قایقی نشسته تک‌دست یک در میان سیم‌کش', 'Cable seated one arm alternate row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، ساعد', '۱. رو به سیم‌کش روی نیمکت بنشینید، کف پاها روی زمین و زانوها کمی خم باشد.
۲. دستگیره را با یک دست بگیرید و دست را کاملاً جلوی بدن صاف نگه دارید.
۳. دستگیره را به سمت بدن بکشید، کتف را جمع کنید و آرنج را نزدیک پهلو نگه دارید.
۴. لحظه‌ای در اوج حرکت مکث کنید و عضلات پشت را منقبض کنید.
۵. دستگیره را آرام به وضعیت شروع برگردانید.
۶. با دست دیگر تکرار کنید.
۷. به تعداد تکرار دلخواه دست‌ها را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0214.gif', 'upper-back', 'biceps,forearm', '1. Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.
2. Grasp the handle with one hand and keep your arm fully extended in front of you.
3. Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.
4. Pause for a moment at the top of the movement, squeezing your back muscles.
5. Slowly release the handle back to the starting position.
6. Repeat with the other arm.
7. Alternate between arms for the desired number of repetitions.', '0214') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1642', 'جلو بازو تمرکزی نشسته تک‌دست سیم‌کش', 'Cable seated one arm concentration curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. روی نیمکت بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. دستگیره سیم‌کش را با یک دست بگیرید و آرنج را روی داخل ران، کمی بالاتر از زانو بگذارید.
۳. بازو را ثابت نگه دارید و با بازدم دستگیره را به سمت شانه بالا بیاورید.
۴. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، دستگیره را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1642.gif', 'biceps', 'forearm', '1. Sit on a bench with your feet flat on the floor and your back straight.
2. Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.
3. Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.
4. Pause for a moment at the top of the movement, squeezing your biceps.
5. Slowly lower the cable handle back to the starting position while inhaling.
6. Repeat for the desired number of repetitions, then switch arms.', '1642') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1643', 'جلو بازو بالای سر نشسته سیم‌کش', 'Cable seated overhead curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد، شانه‌ها', '۱. رو به سیم‌کش روی نیمکت بنشینید و کف پاها را روی زمین بگذارید.
۲. دستگیره کابل را از زیر با کف دست رو به بالا و دست‌ها به اندازه عرض شانه بگیرید.
۳. بازوها را ثابت و آرنج‌ها را نزدیک پهلوها نگه دارید.
۴. با بازدم دستگیره را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۵. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۶. با دم، دستگیره را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1643.gif', 'biceps', 'forearm,deltoids', '1. Sit on a bench facing the cable machine with your feet flat on the ground.
2. Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.
3. Keep your upper arms stationary and your elbows close to your sides.
4. Exhale and curl the cable attachment towards your shoulders, contracting your biceps.
5. Pause for a moment at the top of the movement, squeezing your biceps.
6. Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '1643') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0215', 'نشر خم نشسته سیم‌کش', 'Cable seated rear lateral raise', 'shoulders', 'سرشانه', 'cable', 'سیم‌کش', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. رو به سیم‌کش روی نیمکت بنشینید و کف پاها را روی زمین بگذارید.
۲. دستگیره‌ها را از رو بگیرید و دست‌ها را صاف جلوی بدن دراز کنید.
۳. با دست‌های صاف، آن‌ها را آرام به طرفین بالا ببرید تا موازی زمین شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0215.gif', 'deltoids', 'trapezius,upper-back', '1. Sit on a bench facing the cable machine with your feet flat on the ground.
2. Grasp the cable handles with an overhand grip and extend your arms straight in front of you.
3. Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.
4. Pause for a moment at the top, then slowly lower your arms back to the starting position.
5. Repeat for the desired number of repetitions.', '0215') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0216', 'چرخش داخلی شانه نشسته سیم‌کش', 'Cable seated shoulder internal rotation', 'shoulders', 'سرشانه', 'cable', 'سیم‌کش', 'سرشانه', 'روتاتور کاف، پشت بازو', '۱. رو به سیم‌کش روی نیمکت یا صندلی بنشینید و کف پاها را روی زمین بگذارید.
۲. دستگیره را با دست صاف جلوی بدن و موازی زمین نگه دارید.
۳. آرنج را کمی خم و کتف‌ها را به عقب و پایین کشیده نگه دارید.
۴. دست را آرام به داخل بچرخانید و دستگیره را به سمت وسط بدن بیاورید.
۵. لحظه‌ای در انتهای حرکت مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0216.gif', 'deltoids', 'triceps', '1. Sit on a bench or chair facing the cable machine with your feet flat on the ground.
2. Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.
3. Keep your elbow slightly bent and your shoulder blades pulled back and down.
4. Slowly rotate your arm inward, bringing the cable handle towards the center of your body.
5. Pause for a moment at the end of the movement, then slowly return to the starting position.
6. Repeat for the desired number of repetitions, then switch arms.', '0216') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2399', 'چرخش تنه نشسته سیم‌کش', 'Cable seated twist', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها', '۱. جلوی سیم‌کش بنشینید، کف پاها روی زمین و زانوها کمی خم باشد.
۲. دستگیره را با دو دست بگیرید و دست‌ها را صاف جلوی بدن دراز کنید.
۳. با میان‌تنه درگیر، تنه را آرام به یک طرف بچرخانید و کابل را از جلوی بدن بکشید.
۴. لحظه‌ای در انتهای دامنه حرکت مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. حرکت را برای طرف دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2399.gif', 'abs', 'obliques', '1. Sit on a cable machine with your feet flat on the ground and your knees slightly bent.
2. Hold the cable handle with both hands and extend your arms straight in front of you.
3. Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.
4. Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.
5. Repeat on the other side.
6. Continue alternating sides for the desired number of repetitions.', '2399') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0218', 'قایقی دست باز نشسته سیم‌کش', 'Cable seated wide-grip row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، ساعد', '۱. روی دستگاه قایقی سیم‌کش بنشینید، کف پاها روی جاپایی و زانوها کمی خم باشد.
۲. دستگیره را باز و از رو با کف دست رو به پایین بگیرید.
۳. کمر را صاف نگه دارید و کمی از لگن به جلو متمایل شوید.
۴. دستگیره را به سمت پایین سینه بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در اوج انقباض مکث کنید.
۶. دستگیره را آرام به وضعیت شروع برگردانید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0218.gif', 'upper-back', 'biceps,forearm', '1. Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.
2. Grasp the handle with a wide overhand grip, palms facing down.
3. Keep your back straight and lean slightly forward from the hips.
4. Pull the handle towards your lower chest, squeezing your shoulder blades together.
5. Pause for a moment at the peak of the contraction.
6. Slowly release the handle back to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '0218') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0219', 'پرس سرشانه سیم‌کش', 'Cable shoulder press', 'shoulders', 'سرشانه', 'cable', 'سیم‌کش', 'سرشانه', 'پشت بازو، بالای پشت', '۱. سیم‌کش را طوری تنظیم کنید که دستگیره‌ها در ارتفاع شانه باشند.
۲. پشت به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره‌ها را از رو بگیرید و تا سطح شانه بالا بیاورید، آرنج‌ها خم و رو به بیرون.
۴. دستگیره‌ها را به بالا پرس کنید تا دست‌ها کاملاً بالای سر صاف شوند.
۵. لحظه‌ای در بالا مکث کنید، سپس دستگیره‌ها را آرام تا سطح شانه پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0219.gif', 'deltoids', 'triceps,upper-back', '1. Adjust the cable machine so that the handles are at shoulder height.
2. Stand facing away from the machine with your feet shoulder-width apart.
3. Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.
4. Press the handles upwards until your arms are fully extended overhead.
5. Pause for a moment at the top, then slowly lower the handles back down to shoulder level.
6. Repeat for the desired number of repetitions.', '0219') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0220', 'شراگ سیم‌کش', 'Cable shrug', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'کول (ذوزنقه)', 'شانه‌ها', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره‌ها را از رو بگیرید و اجازه دهید دست‌ها جلوی بدن آویزان باشند.
۳. با دست‌های صاف، شانه‌ها را به سمت گوش‌ها بالا بیندازید.
۴. انقباض را لحظه‌ای نگه دارید، سپس شانه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0220.gif', 'trapezius', 'deltoids', '1. Stand facing the cable machine with your feet shoulder-width apart.
2. Grasp the cable handles with an overhand grip and let your arms hang down in front of you.
3. Keeping your arms straight, shrug your shoulders up towards your ears.
4. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.
5. Repeat for the desired number of repetitions.', '0220') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0222', 'خم شدن جانبی سیم‌کش', 'Cable side bend', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دستگیره سیم‌کش را با یک دست بگیرید.
۲. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. آرام از کمر به پهلو خم شوید و دستگیره را به سمت زانو پایین ببرید.
۴. لحظه‌ای مکث کنید، سپس به وضعیت شروع برگردید.
۵. حرکت را برای طرف دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه طرفین را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0222.gif', 'abs', 'obliques', '1. Stand with your feet shoulder-width apart and grasp the cable handle with one hand.
2. Keep your back straight and your core engaged.
3. Slowly bend sideways at the waist, lowering the cable handle towards your knee.
4. Pause for a moment, then return to the starting position.
5. Repeat on the other side.
6. Alternate sides for the desired number of repetitions.', '0222') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0221', 'کرانچ جانبی سیم‌کش (روی بوسو)', 'Cable side bend crunch (bosu ball)', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دستگیره سیم‌کش را در یک دست نگه دارید.
۲. دست دیگر را روی لگن بگذارید.
۳. میان‌تنه را درگیر کنید و آرام به سمت دستی که کابل را گرفته خم شوید و کمر را صاف نگه دارید.
۴. لحظه‌ای در پایین حرکت مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0221.gif', 'abs', 'obliques', '1. Stand with your feet shoulder-width apart, holding a cable handle in one hand.
2. Place the other hand on your hip.
3. Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.
4. Pause for a moment at the bottom of the movement, then slowly return to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '0221') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0223', 'کرانچ پهلو سیم‌کش', 'Cable side crunch', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها', '۱. یک دستگیره را به قرقره پایین وصل کنید و به پهلو نسبت به دستگاه بایستید.
۲. دستگیره را با دستی که از دستگاه دورتر است بگیرید و دست دیگر را روی لگن بگذارید.
۳. پاها را به اندازه عرض شانه باز و زانوها را کمی خم نگه دارید.
۴. با شکم درگیر، از کمر به پهلو خم شوید و آرنج را به سمت لگن پایین ببرید.
۵. لحظه‌ای در پایین مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0223.gif', 'abs', 'obliques', '1. Attach a cable handle to a low pulley and stand sideways to the machine.
2. Grasp the handle with the hand furthest from the machine and place your other hand on your hip.
3. Keep your feet shoulder-width apart and your knees slightly bent.
4. With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.
5. Pause for a moment at the bottom, then slowly return to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '0223') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1717', 'اسکوات و قایقی سیم‌کش (با طناب)', 'Cable squat row (with rope attachment)', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. یک طناب را در ارتفاع کمر به سیم‌کش وصل کنید.
۲. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. زانوها را خم کنید و به حالت اسکوات پایین بروید و کمر را صاف و سینه را بالا نگه دارید.
۴. طناب را از رو و با دست‌ها به اندازه عرض شانه بگیرید.
۵. میان‌تنه را درگیر کنید و طناب را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۶. آرنج‌ها را نزدیک بدن نگه دارید و تا جایی بکشید که دست‌ها به سینه برسند.
۷. لحظه‌ای در اوج حرکت مکث کنید، سپس طناب را آرام رها کنید و دست‌ها را به وضعیت شروع صاف کنید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1717.gif', 'upper-back', 'biceps,deltoids', '1. Attach a rope to a cable machine at waist height.
2. Stand facing the cable machine with your feet shoulder-width apart.
3. Bend your knees and lower your body into a squat position, keeping your back straight and chest up.
4. Grasp the rope with an overhand grip, with your hands shoulder-width apart.
5. Engage your core and pull the rope towards your body, squeezing your shoulder blades together.
6. Keep your elbows close to your body and continue pulling until your hands reach your chest.
7. Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.
8. Repeat for the desired number of repetitions.', '1717') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1644', 'جلو بازو در حالت اسکوات سیم‌کش', 'Cable squatting curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. یک دستگیره را در پایین‌ترین ارتفاع به سیم‌کش وصل کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره را از زیر با کف دست رو به بالا و دست‌های کاملاً صاف بگیرید.
۴. به حالت اسکوات پایین بروید و کمر را صاف و زانوها را پشت پنجه پاها نگه دارید.
۵. هنگام پایین رفتن در اسکوات، دستگیره را به سمت شانه‌ها بالا بیاورید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۶. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۷. دستگیره را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1644.gif', 'biceps', 'forearm', '1. Attach a cable handle to the lowest setting on a cable machine.
2. Stand facing the machine with your feet shoulder-width apart.
3. Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.
4. Lower your body into a squat position, keeping your back straight and knees behind your toes.
5. As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.
6. Pause for a moment at the top of the curl, squeezing your biceps.
7. Slowly lower the cable handle back to the starting position, fully extending your arms.
8. Repeat for the desired number of repetitions.', '1644') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0224', 'مچ دست از پشت ایستاده سیم‌کش', 'Cable standing back wrist curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'ساعد', 'جلو بازو، بازویی', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره سیم‌کش را از رو با کف دست رو به پایین بگیرید.
۳. دست‌ها را صاف و آرنج‌ها را نزدیک پهلوها نگه دارید.
۴. مچ‌ها را آرام به سمت بالا خم کنید و دستگیره را به سمت بدن بیاورید.
۵. لحظه‌ای در بالا مکث کنید، سپس دستگیره را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0224.gif', 'forearm', 'biceps', '1. Stand facing a cable machine with your feet shoulder-width apart.
2. Hold the cable handle with an overhand grip, palms facing down.
3. Keep your arms straight and your elbows close to your sides.
4. Slowly curl your wrists upward, bringing the cable handle towards your body.
5. Pause for a moment at the top, then slowly lower the cable handle back to the starting position.
6. Repeat for the desired number of repetitions.', '0224') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1375', 'ساق پا ایستاده سیم‌کش', 'Cable standing calf raise', 'legs', 'پا', 'cable', 'سیم‌کش', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره‌های سیم‌کش را بگیرید یا بند مچ پای سیم‌کش را به مچ پاها ببندید.
۳. با باز کردن مچ پاها، پاشنه‌ها را تا جای ممکن از زمین بلند کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1375.gif', 'calves', 'hamstring,gluteal', '1. Stand facing a cable machine with your feet shoulder-width apart.
2. Hold onto the cable machine handles or attach a cable ankle strap to your ankles.
3. Raise your heels off the ground by extending your ankles as high as possible.
4. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
5. Repeat for the desired number of repetitions.', '1375') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0225', 'قفسه معکوس کراس‌اور بالا ایستاده سیم‌کش', 'Cable standing cross-over high reverse fly', 'shoulders', 'سرشانه', 'cable', 'سیم‌کش', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع، دلتوئید خلفی', '۱. یک دستگیره D را به هر طرف سیم‌کش در ارتفاع شانه وصل کنید.
۲. وسط سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره‌ها را از رو بگیرید و دست‌ها را با کف دست رو به جلو به طرفین باز کنید.
۴. در طول تمرین آرنج‌ها را کمی خم و کمر را صاف نگه دارید.
۵. عضلات شانه را درگیر کنید و با کشیدن دستگیره‌ها به جلوی بدن، کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در اوج حرکت مکث کنید، سپس آرام به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0225.gif', 'deltoids', 'trapezius,upper-back', '1. Attach a D-handle to each side of a cable machine at shoulder height.
2. Stand in the middle of the cable machine with your feet shoulder-width apart.
3. Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.
4. Keep a slight bend in your elbows and maintain a straight back throughout the exercise.
5. Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.
6. Pause for a moment at the peak of the movement, then slowly return to the starting position.
7. Repeat for the desired number of repetitions.', '0225') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0226', 'کرانچ ایستاده سیم‌کش', 'Cable standing crunch', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها', '۱. یک دستگیره را به قرقره بالا وصل کنید و پشت به دستگاه بایستید.
۲. دستگیره را با دو دست بگیرید و پشت سر قرار دهید و آرنج‌ها را خم نگه دارید.
۳. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۴. با شکم درگیر، با بازدم تنه را به سمت زانوها خم کنید و آرنج‌ها را به ران‌ها نزدیک کنید.
۵. لحظه‌ای در پایین حرکت مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0226.gif', 'abs', 'obliques', '1. Attach a cable handle to a high pulley and stand facing away from the machine.
2. Hold the handle with both hands and place it behind your head, keeping your elbows bent.
3. Stand with your feet shoulder-width apart and your knees slightly bent.
4. Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.
5. Pause for a moment at the bottom of the movement, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '0226') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0874', 'کرانچ ایستاده سیم‌کش (با طناب)', 'Cable standing crunch (with rope attachment)', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها', '۱. یک طناب را در ارتفاع سینه به سیم‌کش وصل کنید.
۲. پشت به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. طناب را با دو دست بگیرید و پشت سر ببرید و آرنج‌ها را خم نگه دارید.
۴. شکم را درگیر کنید و تنه را آرام به جلو خم کنید و آرنج‌ها را به سمت زانوها ببرید.
۵. لحظه‌ای در بالای کرانچ مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0874.gif', 'abs', 'obliques', '1. Attach a rope to a cable machine at chest height.
2. Stand facing away from the machine with your feet shoulder-width apart.
3. Hold the rope with both hands and bring it behind your head, keeping your elbows bent.
4. Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.
5. Pause for a moment at the top of the crunch, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '0874') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0228', 'باز کردن لگن ایستاده سیم‌کش', 'Cable standing hip extension', 'legs', 'پا', 'cable', 'سیم‌کش', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. یک کابل را به قرقره پایین وصل کنید و پشت به دستگاه بایستید.
۲. کابل را به مچ پا ببندید و پاها را به اندازه عرض شانه باز کنید.
۳. در طول تمرین میان‌تنه را درگیر و کمر را صاف نگه دارید.
۴. پا را آرام صاف به عقب ببرید و در اوج حرکت باسن را منقبض کنید.
۵. لحظه‌ای مکث کنید، سپس به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.
۷. طرف را عوض کنید و با پای دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0228.gif', 'gluteal', 'hamstring,quadriceps', '1. Attach a cable to a low pulley and stand facing away from the machine.
2. Place the cable around your ankle and stand with your feet shoulder-width apart.
3. Keep your core engaged and your back straight throughout the exercise.
4. Slowly extend your leg straight back, squeezing your glutes at the top of the movement.
5. Pause for a moment, then return to the starting position.
6. Repeat for the desired number of repetitions.
7. Switch sides and repeat with the other leg.', '0228') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0229', 'جلو بازو داخلی ایستاده سیم‌کش', 'Cable standing inner curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره سیم‌کش را از زیر با کف دست رو به بالا بگیرید.
۳. آرنج‌ها را نزدیک پهلوها و بازوها را ثابت نگه دارید.
۴. با بازدم دستگیره را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۵. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۶. با دم، دستگیره را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0229.gif', 'biceps', 'forearm', '1. Stand facing a cable machine with your feet shoulder-width apart.
2. Grasp the cable handle with an underhand grip, palms facing up.
3. Keep your elbows close to your sides and your upper arms stationary.
4. Exhale and curl the cable handle towards your shoulders, contracting your biceps.
5. Pause for a moment at the top of the movement, squeezing your biceps.
6. Inhale and slowly lower the cable handle back to the starting position.
7. Repeat for the desired number of repetitions.', '0229') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0230', 'لیفت ایستاده سیم‌کش', 'Cable standing lift', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها، پایین کمر', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره را با دو دست در ارتفاع کمر نگه دارید.
۳. در طول تمرین میان‌تنه را درگیر و کمر را صاف نگه دارید.
۴. با دست‌های صاف و بازدم، دستگیره را با چرخش تنه به سمت شانه مخالف بالا بیاورید.
۵. لحظه‌ای در بالا مکث کنید، سپس با دم دستگیره را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0230.gif', 'abs', 'obliques,lower-back', '1. Stand facing the cable machine with your feet shoulder-width apart.
2. Hold the cable handle with both hands and position it at waist height.
3. Engage your core and maintain a straight back throughout the exercise.
4. Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.
5. Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '0230') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0231', 'پشت بازو تک‌دست ایستاده سیم‌کش', 'Cable standing one arm triceps extension', 'arms', 'بازو', 'cable', 'سیم‌کش', 'پشت بازو', 'شانه‌ها', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره را با دست راست و کف دست رو به پایین بگیرید و دست را کاملاً صاف و موازی زمین نگه دارید.
۳. آرنج را ثابت و نزدیک بدن نگه دارید.
۴. آرنج را آرام خم کنید و دستگیره را به سمت پشت سر پایین بیاورید.
۵. لحظه‌ای در پایین حرکت مکث کنید، سپس دست را به وضعیت شروع صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید و با دست چپ انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0231.gif', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart, facing the cable machine.
2. Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.
3. Keep your elbow stationary and close to your body.
4. Slowly bend your elbow, lowering the cable handle towards the back of your head.
5. Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.
6. Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm.', '0231') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1376', 'ساق پا تک‌پا ایستاده سیم‌کش', 'Cable standing one leg calf raise', 'legs', 'پا', 'cable', 'سیم‌کش', 'ساق پا', 'مچ پا، پاها', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. برای حمایت سیم‌کش را بگیرید.
۳. یک پا را از زمین بلند کنید و روی پای دیگر تعادل بگیرید.
۴. پاشنه را آرام از زمین بلند کنید و بدن را روی پنجه پا بالا ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاشنه را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1376.gif', 'calves', '', '1. Stand facing a cable machine with your feet shoulder-width apart.
2. Hold onto the cable machine for support.
3. Lift one leg off the ground and balance on the other leg.
4. Slowly raise your heel off the ground, lifting your body up onto your toes.
5. Pause for a moment at the top, then slowly lower your heel back down to the starting position.
6. Repeat for the desired number of repetitions, then switch legs.', '1376') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0232', 'زیربغل ایستاده سیم‌کش (با طناب)', 'Cable standing pulldown (with rope)', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد، شانه‌ها', '۱. یک طناب را در بالاترین ارتفاع به سیم‌کش وصل کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. طناب را از رو با کف دست رو به پایین بگیرید.
۴. در طول تمرین کمر را صاف و میان‌تنه را درگیر نگه دارید.
۵. طناب را به سمت ران‌ها پایین بکشید و جلو بازو را منقبض کنید.
۶. لحظه‌ای در پایین مکث کنید، سپس طناب را آرام به بالا برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0232.gif', 'biceps', 'forearm,deltoids', '1. Attach a rope to the cable machine at the highest setting.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the rope with an overhand grip, palms facing down.
4. Keep your back straight and core engaged throughout the exercise.
5. Pull the rope down towards your thighs, squeezing your biceps.
6. Pause for a moment at the bottom, then slowly release the rope back up.
7. Repeat for the desired number of repetitions.', '0232') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0233', 'زیربغل دلتوئید خلفی ایستاده سیم‌کش (با طناب)', 'Cable standing rear delt row (with rope)', 'shoulders', 'سرشانه', 'cable', 'سیم‌کش', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع، جلو بازو', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره کابل را با دو دست و کف دست‌های رو به هم بگیرید و یک قدم عقب بروید تا کابل کشیده شود.
۳. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۴. کابل را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس کابل را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0233.gif', 'deltoids', 'trapezius,upper-back,biceps', '1. Stand facing a cable machine with your feet shoulder-width apart.
2. Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.
3. Keep your back straight and your core engaged.
4. Pull the cable towards your body, squeezing your shoulder blades together.
5. Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.
6. Repeat for the desired number of repetitions.', '0233') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1727', 'پشت بازو بالای سر تک‌دست دست‌برعکس ایستاده سیم‌کش', 'Cable standing reverse grip one arm overhead tricep extension', 'arms', 'بازو', 'cable', 'سیم‌کش', 'پشت بازو', 'شانه‌ها', '۱. پشت به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره را از زیر بگیرید و دست را بالای سر صاف کنید و آرنج را نزدیک سر نگه دارید.
۳. بازو را ثابت نگه دارید و با خم کردن آرنج دستگیره را آرام پشت سر پایین ببرید.
۴. لحظه‌ای در پایین مکث کنید، سپس دست را به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1727.gif', 'triceps', 'deltoids', '1. Stand facing away from the cable machine with your feet shoulder-width apart.
2. Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.
3. Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.
4. Pause for a moment at the bottom, then extend your arm back to the starting position.
5. Repeat for the desired number of repetitions, then switch arms.', '1727') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0234', 'قایقی ایستاده سیم‌کش (دستگیره V)', 'Cable standing row (v-bar)', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره V را از رو با کف دست رو به پایین بگیرید.
۳. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۴. دستگیره V را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس کشش را آرام رها کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0234.gif', 'upper-back', 'biceps,deltoids', '1. Stand facing the cable machine with your feet shoulder-width apart.
2. Grasp the v-bar attachment with an overhand grip, palms facing down.
3. Keep your back straight and your core engaged.
4. Pull the v-bar towards your body, squeezing your shoulder blades together.
5. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.
6. Repeat for the desired number of repetitions.', '0234') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0235', 'چرخش خارجی شانه ایستاده سیم‌کش', 'Cable standing shoulder external rotation', 'shoulders', 'سرشانه', 'cable', 'سیم‌کش', 'سرشانه', 'روتاتور کاف، کول (ذوزنقه)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. دستگیره را با دست صاف جلوی بدن و موازی زمین نگه دارید.
۳. آرنج را کمی خم و کتف‌ها را عقب کشیده نگه دارید.
۴. دست را آرام به بیرون و دور از بدن بچرخانید و آرنج را در همان وضعیت نگه دارید.
۵. لحظه‌ای در انتهای حرکت مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0235.gif', 'deltoids', 'trapezius', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Hold the cable handle with your arm extended in front of you, parallel to the ground.
3. Keep your elbow slightly bent and your shoulder blades pulled back.
4. Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.
5. Pause for a moment at the end of the movement, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '0235') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0236', 'قایقی چرخشی ایستاده سیم‌کش (دستگیره V)', 'Cable standing twist row (v-bar)', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. یک دستگیره V را در ارتفاع سینه به سیم‌کش وصل کنید.
۲. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره V را از رو با کف دست رو به پایین بگیرید.
۴. یک قدم عقب بروید تا کابل کشیده شود.
۵. در طول تمرین کمر را صاف و میان‌تنه را درگیر نگه دارید.
۶. با جمع کردن کتف‌ها و خم کردن آرنج‌ها دستگیره V را به سمت تنه بکشید.
۷. هنگام کشیدن، تنه را به یک طرف بچرخانید و کتف‌ها را به هم فشار دهید.
۸. لحظه‌ای در اوج حرکت مکث کنید و انقباض بالای کمر را حس کنید.
۹. کشش را آرام رها کنید و با برگرداندن چرخش تنه به وضعیت شروع برگردید.
۱۰. به تعداد تکرار دلخواه انجام دهید و جهت چرخش را در هر تکرار عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0236.gif', 'upper-back', 'biceps,deltoids', '1. Attach a v-bar attachment to a cable machine at chest height.
2. Stand facing the cable machine with your feet shoulder-width apart.
3. Grasp the v-bar with an overhand grip, palms facing down.
4. Take a step back to create tension in the cable.
5. Keep your back straight and core engaged throughout the exercise.
6. Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.
7. As you pull, twist your torso to one side, squeezing your shoulder blades together.
8. Pause for a moment at the top of the movement, feeling the contraction in your upper back.
9. Slowly release the tension and return to the starting position, untwisting your torso.
10. Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep.', '0236') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1269', 'کراس‌اور ایستاده صاف سیم‌کش', 'Cable standing up straight crossovers', 'chest', 'سینه', 'cable', 'سیم‌کش', 'سینه', 'سرشانه، پشت بازو', '۱. وسط سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره‌ها را با کف دست رو به پایین بگیرید و دست‌ها را صاف به طرفین باز کنید.
۳. با دست‌های صاف، دست‌ها را جلوی بدن به هم برسانید و از روی هم رد کنید.
۴. لحظه‌ای مکث کنید، سپس با دست‌های کشیده آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1269.gif', 'chest', 'deltoids,triceps', '1. Stand in the middle of a cable machine with your feet shoulder-width apart.
2. Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.
3. Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.
4. Pause for a moment, then slowly return to the starting position, keeping your arms extended.
5. Repeat for the desired number of repetitions.', '1269') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0237', 'پول‌داون دست صاف سیم‌کش (با طناب)', 'Cable straight arm pulldown (with rope)', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'زیربغل', 'جلو بازو، ساعد', '۱. یک طناب را در بالاترین ارتفاع به سیم‌کش وصل کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. طناب را با دو دست و کف دست رو به پایین بگیرید.
۴. دست‌ها را کاملاً جلوی بدن صاف کنید و آرنج‌ها را کمی خم نگه دارید.
۵. زیربغل را درگیر کنید و با دست‌های صاف طناب را آرام به سمت ران‌ها پایین بکشید.
۶. لحظه‌ای در پایین مکث کنید، سپس کشش را آرام رها کنید و به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0237.gif', 'upper-back', 'biceps,forearm', '1. Attach a rope to the cable machine at the highest setting.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the rope with both hands, palms facing down.
4. Extend your arms fully in front of you, keeping your elbows slightly bent.
5. Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.
6. Pause for a moment at the bottom, then slowly release the tension and return to the starting position.
7. Repeat for the desired number of repetitions.', '0237') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0239', 'قایقی نشسته کمر صاف سیم‌کش', 'Cable straight back seated row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، ساعد، شانه‌ها', '۱. روی دستگاه قایقی سیم‌کش بنشینید، کف پاها روی جاپایی و زانوها کمی خم باشد.
۲. دستگیره‌های کابل را از رو با کف دست رو به پایین بگیرید.
۳. کمر را صاف نگه دارید و کمی از لگن به جلو متمایل شوید.
۴. دستگیره‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0239.gif', 'upper-back', 'biceps,forearm,deltoids', '1. Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.
2. Grasp the cable handles with an overhand grip, palms facing down.
3. Keep your back straight and lean slightly forward from the hips.
4. Pull the cable handles towards your body, squeezing your shoulder blades together.
5. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.
6. Repeat for the desired number of repetitions.', '0239') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0240', 'قفسه معکوس خوابیده سیم‌کش', 'Cable supine reverse fly', 'shoulders', 'سرشانه', 'cable', 'سیم‌کش', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. یک دستگیره D را به قرقره پایین وصل کنید و روی نیمکت صاف دمر دراز بکشید.
۲. دستگیره‌ها را با هر دست و کف دست رو به پایین بگیرید و دست‌ها را صاف جلوی بدن دراز کنید.
۳. با دست‌های صاف، آن‌ها را به طرفین بالا ببرید تا موازی زمین شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0240.gif', 'deltoids', 'trapezius,upper-back', '1. Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.
2. Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.
3. Keeping your arms straight, raise them out to the sides until they are parallel to the floor.
4. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
5. Repeat for the desired number of repetitions.', '0240') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2464', 'قایقی کایاکی تیبادو سیم‌کش', 'Cable thibaudeau kayak row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. یک دستگیره را به قرقره پایین وصل کنید و رو به دستگاه بنشینید و کف پاها را روی زمین بگذارید.
۲. دستگیره را با دست راست بگیرید و دست را کاملاً صاف کنید و آرنج را کمی خم نگه دارید.
۳. از لگن به جلو متمایل شوید و کمر را صاف و شکم را درگیر نگه دارید.
۴. با جمع کردن کتف و خم کردن آرنج، دستگیره را به سمت تنه بکشید و دست را نزدیک بدن نگه دارید.
۵. در اوج حرکت عضلات پشت را منقبض کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید و با دست چپ انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2464.gif', 'upper-back', 'biceps,deltoids', '1. Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.
2. Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.
3. Lean forward from your hips, keeping your back straight and your abs engaged.
4. Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.
5. Squeeze your back muscles at the top of the movement, then slowly return to the starting position.
6. Repeat for the desired number of repetitions, then switch sides and perform with your left arm.', '2464') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2405', 'پشت بازو سیم‌کش با دستگیره V و آرم‌بلستر', 'Cable triceps pushdown (v-bar) (with arm blaster)', 'arms', 'بازو', 'cable', 'سیم‌کش', 'پشت بازو', 'ساعد', '۱. یک دستگیره V را در بالاترین ارتفاع به سیم‌کش وصل کنید.
۲. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره V را از رو با کف دست رو به پایین و دست‌ها به اندازه عرض شانه بگیرید.
۴. در طول تمرین آرنج‌ها را نزدیک پهلوها و بازوها را ثابت نگه دارید.
۵. پشت بازو را درگیر کنید و با بازدم دستگیره را پایین فشار دهید تا دست‌ها کاملاً صاف شوند.
۶. لحظه‌ای در پایین حرکت مکث کنید و پشت بازو را منقبض کنید.
۷. با دم، دستگیره V را آرام و با کنترل به وضعیت شروع برگردانید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2405.gif', 'triceps', 'forearm', '1. Attach a v-bar attachment to the cable machine at the highest setting.
2. Stand facing the cable machine with your feet shoulder-width apart.
3. Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.
4. Keep your elbows close to your sides and your upper arms stationary throughout the exercise.
5. Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.
6. Pause for a moment at the bottom of the movement, squeezing your triceps.
7. Inhale as you slowly return the v-bar to the starting position, maintaining control.
8. Repeat for the desired number of repetitions.', '2405') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0242', 'کرانچ معکوس جمع‌شده سیم‌کش', 'Cable tuck reverse crunch', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'خم‌کننده ران', '۱. یک کابل را به قرقره پایین وصل کنید و به پشت روی تشک دراز بکشید.
۲. کابل را با دو دست بگیرید و دست‌ها را صاف بالای سینه ببرید.
۳. زانوها را خم کنید و پاها را بالا بیاورید و زانوها را به سمت سینه ببرید.
۴. همزمان لگن را به سمت سینه جمع کنید و باسن را از زمین بلند کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاها و لگن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0242.gif', 'abs', 'hip-flexors', '1. Attach a cable to a low pulley and lie down on a mat facing up.
2. Hold the cable with both hands and extend your arms straight up above your chest.
3. Bend your knees and lift your legs up, bringing your knees towards your chest.
4. At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.
5. Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.
6. Repeat for the desired number of repetitions.', '0242') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0243', 'چرخش تنه سیم‌کش', 'Cable twist', 'core', 'شکم و میان‌تنه', 'cable', 'سیم‌کش', 'شکم', 'پهلوها', '۱. رو به سیم‌کش بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دستگیره را با دو دست جلوی سینه نگه دارید و دست‌ها را کمی خم نگه دارید.
۳. میان‌تنه را درگیر کنید و تنه را به راست بچرخانید و کابل را از جلوی بدن بکشید.
۴. لحظه‌ای در انتهای حرکت مکث کنید و انقباض شکم و پهلوها را حس کنید.
۵. در برابر کشش کابل مقاومت کنید و آرام به وضعیت شروع برگردید.
۶. حرکت را به سمت چپ تکرار کنید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0243.gif', 'abs', 'obliques', '1. Stand with your feet shoulder-width apart, facing the cable machine.
2. Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.
3. Engage your core and twist your torso to the right, pulling the cable across your body.
4. Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.
5. Slowly return to the starting position, resisting the cable''s pull.
6. Repeat the movement to the left side.
7. Continue alternating sides for the desired number of repetitions.', '0243') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0244', 'کشش چرخشی سیم‌کش', 'Cable twisting pull', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'زیربغل', 'شانه‌ها، جلو بازو', '۱. یک دستگیره را به قرقره پایین وصل کنید و رو به دستگاه بایستید.
۲. دستگیره را با دست چپ بگیرید و از دستگاه فاصله بگیرید و دست را کاملاً صاف کنید.
۳. پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم نگه دارید.
۴. در طول تمرین کمر را صاف و میان‌تنه را درگیر نگه دارید.
۵. دستگیره را به سمت بدن بکشید و همزمان تنه را به راست بچرخانید.
۶. در انتهای حرکت عضلات پشت را منقبض کنید.
۷. آرام به وضعیت شروع برگردید و کابل را کشیده نگه دارید.
۸. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید و با دست راست انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0244.gif', 'upper-back', 'deltoids,biceps', '1. Attach a cable handle to a low pulley and stand facing the machine.
2. Grasp the handle with your left hand and step away from the machine, extending your arm fully.
3. Position your feet shoulder-width apart, with your knees slightly bent.
4. Keep your back straight and your core engaged throughout the exercise.
5. Pull the handle towards your body, rotating your torso to the right as you do so.
6. Squeeze your back muscles at the end of the movement.
7. Slowly return to the starting position, keeping tension on the cable.
8. Repeat for the desired number of repetitions, then switch sides and perform with your right hand.', '0244') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1645', 'جلو بازو دو دست روی نیمکت شیب‌دار سیم‌کش', 'Cable two arm curl on incline bench', 'arms', 'بازو', 'cable', 'سیم‌کش', 'جلو بازو', 'ساعد', '۱. روی نیمکت شیب‌دار بنشینید، کمر به پد و کف پاها روی زمین باشد.
۲. دستگیره‌ها را از زیر با کف دست رو به بالا و دست‌های کاملاً صاف بگیرید.
۳. بازوها را ثابت نگه دارید و با بازدم دستگیره‌ها را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۴. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۵. با دم، دستگیره‌ها را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1645.gif', 'biceps', 'forearm', '1. Sit on an incline bench with your back against the pad and your feet flat on the ground.
2. Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.
3. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.
4. Pause for a moment at the top of the movement, squeezing your biceps.
5. Inhale and slowly lower the handles back to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '1645') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1728', 'کیک‌بک دو دست سیم‌کش', 'Cable two arm tricep kickback', 'arms', 'بازو', 'cable', 'سیم‌کش', 'پشت بازو', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. در هر دست یک دستگیره را با کف دست رو به داخل بگیرید و دست‌ها را ۹۰ درجه خم کنید.
۳. بازوها را ثابت نگه دارید و ساعدها را به عقب باز کنید تا دست‌ها کاملاً صاف شوند.
۴. لحظه‌ای مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1728.gif', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and knees slightly bent.
2. Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.
3. Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.
4. Pause for a moment, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '1728') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0245', 'زیربغل دست‌برعکس سیم‌کش', 'Cable underhand pulldown', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'زیربغل', 'جلو بازو، ساعد', '۱. سیم‌کش را طوری تنظیم کنید که میله زیربغل بالاتر از سر باشد.
۲. روی صندلی بنشینید و میله را از زیر و کمی بازتر از عرض شانه بگیرید.
۳. کمر را صاف نگه دارید و کمی به عقب متمایل شوید.
۴. میله را به سمت سینه پایین بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در پایین حرکت مکث کنید، سپس میله را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0245.gif', 'upper-back', 'biceps,forearm', '1. Adjust the cable machine so that the pulldown bar is at a height above your head.
2. Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.
3. Keep your back straight and lean back slightly.
4. Pull the bar down towards your chest, squeezing your shoulder blades together.
5. Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.
6. Repeat for the desired number of repetitions.', '0245') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1270', 'کراس‌اور بالاسینه سیم‌کش', 'Cable upper chest crossovers', 'chest', 'سینه', 'cable', 'سیم‌کش', 'سینه', 'سرشانه، پشت بازو', '۱. دستگیره‌ها را در ارتفاع سینه به کابل‌ها وصل کنید.
۲. وسط سیم‌کش بایستید و یک پا را کمی جلوتر از پای دیگر بگذارید.
۳. دستگیره‌ها را با کف دست رو به پایین بگیرید و دست‌ها را به طرفین باز کنید.
۴. آرنج‌ها را کمی خم نگه دارید و میان‌تنه را درگیر کنید.
۵. کابل‌ها را جلوی سینه به هم بکشید و از روی هم رد کنید.
۶. در اوج حرکت عضلات سینه را منقبض کنید.
۷. کابل‌ها را آرام به وضعیت شروع برگردانید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1270.gif', 'chest', 'deltoids,triceps', '1. Attach the handles to the cables at chest height.
2. Stand in the center of the cable machine with one foot slightly in front of the other.
3. Grasp the handles with your palms facing down and your arms extended out to the sides.
4. Keep a slight bend in your elbows and engage your core.
5. Pull the cables together in front of your chest, crossing them over each other.
6. Squeeze your chest muscles at the peak of the movement.
7. Slowly release the cables back to the starting position.
8. Repeat for the desired number of repetitions.', '1270') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1324', 'قایقی بالا سیم‌کش', 'Cable upper row', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. یک میله صاف را در ارتفاع سینه به سیم‌کش وصل کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۴. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۵. میله را به سمت بالای سینه بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در اوج حرکت مکث کنید.
۷. میله را آرام به وضعیت شروع برگردانید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1324.gif', 'upper-back', 'biceps,deltoids', '1. Attach a straight bar to a cable machine at chest height.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.
4. Keep your back straight and your core engaged.
5. Pull the bar towards your upper chest, squeezing your shoulder blades together.
6. Pause for a moment at the top of the movement.
7. Slowly release the bar back to the starting position.
8. Repeat for the desired number of repetitions.', '1324') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0246', 'کول ایستاده سیم‌کش', 'Cable upright row', 'shoulders', 'سرشانه', 'cable', 'سیم‌کش', 'سرشانه', 'کول (ذوزنقه)، جلو بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز و زانوها کمی خم باشد و دستگیره کابل را از رو بگیرید.
۲. در طول تمرین کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. دستگیره را با هدایت آرنج‌ها مستقیم به سمت چانه بالا بکشید.
۴. لحظه‌ای در بالا مکث کنید و کتف‌ها را به هم فشار دهید.
۵. دستگیره را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0246.gif', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.
2. Keep your back straight and your core engaged throughout the exercise.
3. Pull the cable attachment straight up towards your chin, leading with your elbows.
4. Pause for a moment at the top, squeezing your shoulder blades together.
5. Slowly lower the cable attachment back down to the starting position.
6. Repeat for the desired number of repetitions.', '0246') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1325', 'زیربغل دست باز پشت گردن سیم‌کش', 'Cable wide grip rear pulldown behind neck', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. سیم‌کش را طوری تنظیم کنید که میله زیربغل بالاتر از سر باشد.
۲. روی صندلی بنشینید و میله زیربغل را باز و از رو بگیرید.
۳. کمر را صاف و سینه را بالا نگه دارید و کمی به عقب متمایل شوید.
۴. میله را به سمت بالای سینه پایین بکشید و کتف‌ها را به هم فشار دهید.
۵. لحظه‌ای در پایین حرکت مکث کنید، سپس میله را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1325.gif', 'upper-back', 'biceps,deltoids', '1. Adjust the cable machine so that the pulldown bar is at a height above your head.
2. Sit down on the seat and grab the pulldown bar with a wide overhand grip.
3. Keep your back straight and your chest up as you lean back slightly.
4. Pull the bar down towards your upper chest, squeezing your shoulder blades together.
5. Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.
6. Repeat for the desired number of repetitions.', '1325') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0247', 'مچ دست سیم‌کش', 'Cable wrist curl', 'arms', 'بازو', 'cable', 'سیم‌کش', 'ساعد', 'جلو بازو، بازویی', '۱. یک میله صاف را به قرقره پایین سیم‌کش وصل کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. میله را از زیر با کف دست رو به بالا و دست‌ها به اندازه عرض شانه بگیرید.
۴. ساعدها را روی نیمکت یا پد بگذارید و مچ‌ها از لبه آویزان باشند.
۵. ساعدها را ثابت نگه دارید و با بازدم، مچ‌ها را تا جای ممکن به سمت بالا خم کنید.
۶. لحظه‌ای در بالا مکث کنید، سپس با دم میله را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0247.gif', 'forearm', 'biceps', '1. Attach a straight bar to a low pulley cable machine.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.
4. Rest your forearms on a bench or pad, with your wrists hanging off the edge.
5. Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.
6. Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.
7. Repeat for the desired number of repetitions.', '0247') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1407', 'کشش ساق پا با فشار دست به دیوار', 'Calf push stretch with hands against wall', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'همسترینگ (پشت ران)', '۱. رو به دیوار بایستید و پاها را به اندازه عرض لگن باز کنید.
۲. دست‌ها را در ارتفاع شانه روی دیوار بگذارید.
۳. یک پا را به عقب ببرید و پاشنه را روی زمین و پا را صاف نگه دارید.
۴. زانوی جلو را کمی خم کنید و به جلو متمایل شوید تا کشش را در ساق پا حس کنید.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۶. پا را عوض کنید و کشش را تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1407.gif', 'calves', 'hamstring', '1. Stand facing a wall with your feet hip-width apart.
2. Place your hands against the wall at shoulder height.
3. Step back with one foot, keeping your heel on the ground and your leg straight.
4. Bend your front knee slightly and lean forward, feeling a stretch in your calf.
5. Hold the stretch for 20-30 seconds.
6. Switch legs and repeat the stretch.', '1407') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1377', 'کشش ساق پا با دست روی دیوار', 'Calf stretch with hands against wall', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'همسترینگ (پشت ران)', '۱. رو به دیوار بایستید و پاها را به اندازه عرض لگن باز کنید.
۲. دست‌ها را در ارتفاع شانه روی دیوار بگذارید.
۳. پای راست را به عقب ببرید و پاشنه را روی زمین و پا را صاف نگه دارید.
۴. زانوی چپ را خم کنید و به جلو متمایل شوید و پای عقب را صاف و پاشنه را روی زمین نگه دارید.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۶. پا را عوض کنید و کشش را تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1377.gif', 'calves', 'hamstring', '1. Stand facing a wall with your feet hip-width apart.
2. Place your hands against the wall at shoulder height.
3. Step your right foot back, keeping your heel on the ground and your leg straight.
4. Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.
5. Hold the stretch for 20-30 seconds.
6. Switch legs and repeat the stretch.', '1377') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1378', 'کشش ساق پا با طناب', 'Calf stretch with rope', 'legs', 'پا', 'other', 'سایر', 'ساق پا', 'همسترینگ (پشت ران)', '۱. رو به دیوار یا یک جسم محکم بایستید و پاها را به اندازه عرض لگن باز کنید.
۲. هر سر طناب را در یک دست بگیرید و وسط طناب را دور پنجه پای راست بیندازید.
۳. پای چپ را به عقب ببرید و پاشنه را روی زمین و پا را صاف نگه دارید.
۴. با کمر صاف به جلو متمایل شوید و طناب را آرام بکشید تا ساق پا کشیده شود.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید و سپس رها کنید.
۶. با پای دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1378.gif', 'calves', 'hamstring', '1. Stand facing a wall or sturdy object with your feet hip-width apart.
2. Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.
3. Step back with your left foot, keeping your heel on the ground and your leg straight.
4. Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.
5. Hold the stretch for 20-30 seconds, then release.
6. Repeat on the other leg.', '1378') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0248', 'زیربغل خوابیده با میله کمبر', 'Cambered bar lying row', 'back', 'پشت و زیربغل', 'barbell', 'هالتر', 'بالای پشت', 'جلو بازو، ساعد', '۱. هالتر را روی زمین بگذارید و روی نیمکت دمر دراز بکشید به طوری که سینه کمی از لبه بیرون باشد.
۲. دست‌ها را پایین ببرید و هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با پاهای صاف و کف پاها روی زمین، هالتر را از زمین بلند کنید.
۴. هالتر را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.
۵. هالتر را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0248.gif', 'upper-back', 'biceps,forearm', '1. Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.
2. Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.
4. Pull the barbell towards your chest, squeezing your shoulder blades together.
5. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', '0248') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2963', 'بالا آوردن پای صاف روی صندلی کاپیتان', 'Captains chair straight leg raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. روی صندلی کاپیتان بنشینید، کمر به پشتی تکیه داشته باشد و ساعدها روی پدهای دسته باشد.
۲. بالاتنه را ثابت و کمر را صاف نگه دارید.
۳. شکم را درگیر کنید و پاها را صاف جلوی بدن بالا بیاورید.
۴. تا جایی بالا بیاورید که پاها موازی زمین شوند یا تا جایی که راحت هستید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2963.gif', 'abs', 'hip-flexors', '1. Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.
2. Keep your upper body stable and your back straight.
3. Engage your abs and lift your legs up in front of you, keeping them straight.
4. Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.
5. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
6. Repeat for the desired number of repetitions.', '2963') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1548', 'کشش پای کشیده روی صندلی', 'Chair leg extended stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'همسترینگ (پشت ران)، ساق پا', '۱. لبه صندلی بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. یک پا را صاف جلوی بدن دراز کنید و پاشنه را روی زمین نگه دارید.
۳. کمی به جلو متمایل شوید تا کشش را در عضلات ران حس کنید.
۴. این وضعیت را ۲۰ تا ۳۰ ثانیه نگه دارید.
۵. پا را عوض کنید و کشش را تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1548.gif', 'quadriceps', 'hamstring,calves', '1. Sit on the edge of a chair with your back straight and feet flat on the ground.
2. Extend one leg straight out in front of you, keeping your heel on the ground.
3. Lean forward slightly, feeling a stretch in your quadriceps.
4. Hold this position for 20-30 seconds.
5. Switch legs and repeat the stretch.', '1548') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1271', 'کشش سینه و جلوی شانه', 'Chest and front of shoulder stretch', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'سرشانه', '۱. صاف بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دست‌ها را صاف جلوی بدن در ارتفاع شانه دراز کنید.
۳. دست‌ها را جلوی بدن ضربدری کنید، دست راست روی دست چپ.
۴. انگشتان را در هم قفل کنید و کف دست‌ها را به هم فشار دهید.
۵. کتف‌ها را آرام به هم فشار دهید و دست‌ها را به جلو هل دهید تا کشش را در سینه و جلوی شانه‌ها حس کنید.
۶. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید و سپس رها کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1271.gif', 'chest', 'deltoids', '1. Stand tall with your feet shoulder-width apart.
2. Extend your arms straight out in front of you at shoulder height.
3. Cross your arms in front of your body, with your right arm on top of your left arm.
4. Interlace your fingers and press your palms together.
5. Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.
6. Hold the stretch for 20-30 seconds, then release.
7. Repeat for the desired number of repetitions.', '1271') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1430', 'دیپ سینه (روی قفس دیپ و بارفیکس)', 'Chest dip (on dip-pull-up cage)', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. میله‌های دیپ را در ارتفاعی تنظیم کنید که راحت بگیرید.
۲. بین میله‌ها بایستید و دست‌ها را کمی بازتر از عرض شانه روی میله‌ها بگذارید.
۳. بالا بپرید و دست‌ها را صاف کنید و وزن بدن را روی میله‌ها نگه دارید.
۴. زانوها را خم کنید و مچ پاها را پشت سر ضربدری کنید.
۵. با خم کردن آرنج‌ها بدن را پایین ببرید و سینه را بالا و شانه‌ها را پایین نگه دارید.
۶. تا جایی پایین بروید که شانه‌ها پایین‌تر از آرنج‌ها قرار گیرند یا کشش را در سینه حس کنید.
۷. با فشار کف دست‌ها و صاف کردن آرنج‌ها بدن را به وضعیت شروع بالا ببرید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1430.gif', 'chest', 'triceps,deltoids', '1. Adjust the dip bars to a height that allows you to comfortably grip them.
2. Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.
3. Jump up and straighten your arms, supporting your body weight on the bars.
4. Bend your knees and cross your ankles behind you.
5. Lower your body by bending your elbows, keeping your chest up and your shoulders down.
6. Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.
7. Push through your palms and extend your elbows to raise your body back up to the starting position.
8. Repeat for the desired number of repetitions.', '1430') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2462', 'دیپ سینه روی میله صاف', 'Chest dip on straight bar', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. میله‌های موازی را با کف دست رو به پایین و دست‌های کاملاً صاف بگیرید.
۲. زانوها را خم کنید و مچ پاها را ضربدری کنید.
۳. با خم کردن دست‌ها بدن را پایین ببرید تا شانه‌ها پایین‌تر از آرنج‌ها قرار گیرند.
۴. با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2462.gif', 'chest', 'triceps,deltoids', '1. Grab the parallel bars with your palms facing down and your arms fully extended.
2. Bend your knees and cross your ankles.
3. Lower your body by bending your arms until your shoulders are below your elbows.
4. Push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '2462') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1272', 'کشش سینه با توپ تعادلی', 'Chest stretch with exercise ball', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'شانه‌ها، پشت بازو', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. توپ تعادلی را با دو دست بگیرید و دست‌ها را صاف جلوی بدن دراز کنید.
۳. توپ را آرام به سمت سینه بیاورید تا کشش را در عضلات سینه حس کنید.
۴. کشش را چند ثانیه نگه دارید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1272.gif', 'chest', 'deltoids,triceps', '1. Sit on the stability ball with your feet flat on the ground and your back straight.
2. Hold the exercise ball with both hands and extend your arms straight out in front of you.
3. Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.
4. Hold the stretch for a few seconds, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '1272') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3216', 'شنا سوئدی با لمس سینه', 'Chest tap push-up (male)', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها کمی بازتر از عرض شانه و بدن در یک خط صاف.
۲. با خم کردن آرنج‌ها بدن را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۳. هنگام پایین رفتن، با دست راست به سینه ضربه بزنید.
۴. خود را به وضعیت شروع بالا ببرید.
۵. حرکت را تکرار کنید و این بار با دست چپ به سینه ضربه بزنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3216.gif', 'chest', 'triceps,deltoids', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.
2. Lower your body towards the ground by bending your elbows, keeping them close to your sides.
3. As you lower yourself, tap your chest with your right hand.
4. Push yourself back up to the starting position.
5. Repeat the movement, this time tapping your chest with your left hand.
6. Continue alternating sides for the desired number of repetitions.', '3216') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1326', 'بارفیکس دست‌برعکس', 'Chin-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. از میله بارفیکس با کف دست رو به خود و دست‌ها به اندازه عرض شانه آویزان شوید.
۲. میان‌تنه را درگیر کنید و با هدایت سینه، بدن را به سمت میله بالا بکشید.
۳. تا جایی بالا بروید که چانه بالای میله قرار بگیرد.
۴. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1326.gif', 'upper-back', 'biceps,forearm', '1. Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.
2. Engage your core and pull your body up towards the bar, leading with your chest.
3. Continue pulling until your chin is above the bar.
4. Pause for a moment at the top, then slowly lower your body back down to the starting position.
5. Repeat for the desired number of repetitions.', '1326') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0257', 'کشش دایره‌ای زانو', 'Circles knee stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'همسترینگ (پشت ران)، چهارسر ران', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را روی لگن بگذارید.
۲. زانوها را کمی خم کنید و پاشنه‌ها را بلند کنید و روی پنجه پاها تعادل بگیرید.
۳. با زانوهای خم، زانوها را به صورت دایره‌ای ابتدا در جهت عقربه‌های ساعت و سپس خلاف آن بچرخانید.
۴. حرکت را به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0257.gif', 'calves', 'hamstring,quadriceps', '1. Stand with your feet shoulder-width apart and your hands on your hips.
2. Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.
3. Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.
4. Perform the movement for the desired number of repetitions.', '0257') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1273', 'شنا سوئدی با کف زدن', 'Clap push up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. در وضعیت پلانک با دست صاف قرار بگیرید و دست‌ها را کمی بازتر از عرض شانه بگذارید.
۲. با خم کردن آرنج‌ها بدن را به سمت زمین پایین ببرید و میان‌تنه را درگیر نگه دارید.
۳. با فشار انفجاری کف دست‌ها، بدن را از زمین بالا پرتاب کنید.
۴. در هوا دست‌ها را به هم بزنید و سپس در وضعیت شروع فرود بیایید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1273.gif', 'chest', 'triceps,deltoids', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart.
2. Lower your body towards the ground by bending your elbows, keeping your core engaged.
3. Push through your palms explosively to propel your body off the ground.
4. While in mid-air, clap your hands together before landing back in the starting position.
5. Repeat for the desired number of repetitions.', '1273') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0258', 'شنا سوئدی ساعتی', 'Clock push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها، میان‌تنه', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها درست زیر شانه‌ها و بدن در یک خط صاف.
۲. با خم کردن آرنج‌ها بدن را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۳. هنگام پایین رفتن، بدن را به چپ بچرخانید و دست چپ را صاف به طرف باز کنید.
۴. به وضعیت شروع بالا بروید و همزمان بدن را به مرکز برگردانید.
۵. شنا را تکرار کنید و این بار بدن را به راست بچرخانید و دست راست را به طرف باز کنید.
۶. در هر تکرار طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0258.gif', 'chest', 'triceps,deltoids,abs', '1. Start in a high plank position with your hands directly under your shoulders and your body in a straight line.
2. Lower your body towards the ground by bending your elbows, keeping them close to your sides.
3. As you lower, rotate your body to the left, extending your left arm straight out to the side.
4. Push back up to the starting position, while rotating your body to the center.
5. Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.
6. Continue alternating sides with each repetition.', '0258') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1327', 'بارفیکس دست‌برعکس دست جمع', 'Close grip chin-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. میله بارفیکس را با کف دست رو به خود و دست‌ها به اندازه عرض شانه بگیرید.
۲. با دست‌های کاملاً صاف و پاهای جدا از زمین از میله آویزان شوید.
۳. عضلات پشت را درگیر کنید و بدن را به سمت میله بالا بکشید و آرنج‌ها را نزدیک بدن نگه دارید.
۴. تا جایی بالا بروید که چانه بالای میله قرار بگیرد.
۵. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1327.gif', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.
2. Hang from the bar with your arms fully extended and your feet off the ground.
3. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.
4. Continue pulling until your chin is above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '1327') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0259', 'شنا سوئدی دست جمع', 'Close-grip push-up', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. در وضعیت پلانک با دست صاف قرار بگیرید و دست‌ها را نزدیک هم، درست زیر شانه‌ها بگذارید.
۲. میان‌تنه را درگیر کنید و بدن را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۳. با فشار کف دست‌ها، دست‌ها را صاف کنید و به وضعیت شروع برگردید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0259.gif', 'triceps', 'chest,deltoids', '1. Start in a high plank position with your hands placed close together, directly under your shoulders.
2. Engage your core and lower your body towards the ground, keeping your elbows close to your sides.
3. Push through your palms to extend your arms and return to the starting position.
4. Repeat for the desired number of repetitions.', '0259') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2398', 'شنا سوئدی دست جمع (روی زانو)', 'Close-grip push-up (on knees)', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. در حالت چهار دست و پا قرار بگیرید؛ دست‌ها به اندازه عرض شانه و زانوها به اندازه عرض لگن باز.
۲. با خم کردن آرنج‌ها بالاتنه را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۳. وقتی سینه کمی بالاتر از زمین قرار گرفت لحظه‌ای مکث کنید.
۴. با فشار کف دست‌ها، دست‌ها را صاف کنید و به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2398.gif', 'triceps', 'chest,deltoids', '1. Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.
2. Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.
3. Pause for a moment when your chest is just above the ground.
4. Push through your palms to straighten your arms and return to the starting position.
5. Repeat for the desired number of repetitions.', '2398') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0260', 'پیله (کوکون)', 'Cocoons', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0260.gif', 'abs', 'hip-flexors,lower-back', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0260') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1468', 'لمس پنجه پا با چرخش خرچنگی', 'Crab twist toe touch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، خم‌کننده ران', '۱. روی زمین بنشینید، زانوها خم و کف پاها روی زمین باشد.
۲. دست‌ها را پشت سر با انگشتان رو به پاها بگذارید و لگن را از زمین بلند کنید.
۳. یک پا را صاف جلوی بدن دراز کنید و همزمان دست مخالف را به سمت پنجه پا ببرید.
۴. به وضعیت شروع برگردید و برای طرف دیگر تکرار کنید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1468.gif', 'abs', 'obliques,hip-flexors', '1. Start by sitting on the ground with your knees bent and feet flat on the floor.
2. Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.
3. Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.
4. Return to the starting position and repeat on the other side.
5. Continue alternating sides for the desired number of repetitions.', '1468') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0262', 'کرانچ ضربدری', 'Cross body crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن شکم، بالاتنه را از زمین بلند کنید و بچرخید تا آرنج راست به زانوی چپ نزدیک شود.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. برای طرف دیگر تکرار کنید و آرنج چپ را به سمت زانوی راست ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0262.gif', 'abs', 'obliques', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat on the other side, bringing your left elbow towards your right knee.
6. Repeat for the desired number of repetitions.', '0262') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0267', 'کرانچ (دست‌ها بالای سر)', 'Crunch (hands overhead)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را صاف بالای سر دراز کنید.
۳. با درگیر کردن شکم، بالاتنه را از زمین بلند کنید و به سمت زانوها خم شوید.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0267.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Extend your arms straight above your head.
3. Engaging your abs, lift your upper body off the ground, curling forward towards your knees.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0267') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0271', 'کرانچ (روی توپ تعادلی)', 'Crunch (on stability ball)', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'خم‌کننده ران', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. روی توپ به عقب دراز بکشید تا پایین کمر حمایت شود و بالاتنه موازی زمین باشد.
۳. دست‌ها را پشت سر یا ضربدری روی سینه بگذارید.
۴. شکم را درگیر کنید و بالاتنه را به سمت زانوها بلند کنید و تنه را به جلو خم کنید.
۵. لحظه‌ای در اوج حرکت مکث کنید، سپس بالاتنه را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0271.gif', 'abs', 'hip-flexors', '1. Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.
3. Place your hands behind your head or across your chest.
4. Engage your abs and lift your upper body towards your knees, curling your torso forward.
5. Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0271') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0272', 'کرانچ (روی توپ تعادلی، دست‌ها صاف)', 'Crunch (on stability ball, arms straight)', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'خم‌کننده ران', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. روی توپ به عقب دراز بکشید تا پایین کمر حمایت شود و بالاتنه موازی زمین باشد.
۳. دست‌ها را پشت سر بگذارید یا روی سینه ضربدری کنید.
۴. شکم را درگیر کنید و بالاتنه را از روی توپ بلند کنید و شانه‌ها را به سمت لگن جمع کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0272.gif', 'abs', 'hip-flexors', '1. Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.
3. Place your hands behind your head or cross them over your chest.
4. Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.
5. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0272') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3016', 'کرل‌آپ', 'Curl-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3016.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3016') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3769', 'اسکوات کرتسی', 'Curtsey squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. با پای راست یک گام مورب به عقب و از پشت پای چپ بردارید.
۳. هر دو زانو را مانند حالت تعظیم خم کنید و بدن را به سمت زمین پایین ببرید.
۴. تنه را صاف و وزن را روی پای جلو نگه دارید.
۵. با فشار پای جلو به وضعیت شروع برگردید.
۶. برای طرف دیگر با گام مورب پای چپ به عقب تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3769.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.
3. Bend both knees as if you were curtsying, lowering your body towards the ground.
4. Keep your torso upright and your weight on your front foot.
5. Push through your front foot to return to the starting position.
6. Repeat on the other side, stepping diagonally behind and across your body with your left foot.', '3769') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0276', 'حشره مرده (دد باگ)', 'Dead bug', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. به پشت صاف دراز بکشید و دست‌ها را به سمت سقف دراز کنید.
۲. زانوها را خم کنید و پاها را از زمین بلند کنید تا لگن و زانوها زاویه ۹۰ درجه بسازند.
۳. میان‌تنه را درگیر کنید و پایین کمر را به زمین فشار دهید.
۴. دست راست و پای چپ را آرام و صاف به سمت زمین پایین ببرید تا کمی بالاتر از زمین معلق بمانند.
۵. لحظه‌ای مکث کنید، سپس به وضعیت شروع برگردید.
۶. حرکت را با دست چپ و پای راست تکرار کنید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0276.gif', 'abs', 'hip-flexors,lower-back', '1. Lie flat on your back with your arms extended towards the ceiling.
2. Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.
3. Engage your core and lower back to press your lower back into the ground.
4. Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.
5. Pause for a moment, then return to the starting position.
6. Repeat the movement with your left arm and right leg.
7. Continue alternating sides for the desired number of repetitions.', '0276') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0277', 'کرانچ روی نیمکت زیرسینه', 'Decline crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. روی نیمکت زیرسینه دراز بکشید، پاها محکم شده و زانوها ۹۰ درجه خم باشد.
۲. دست‌ها را پشت سر یا ضربدری روی سینه بگذارید.
۳. شکم را درگیر کنید و بالاتنه را به سمت زانوها بلند کنید و تنه را جمع کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0277.gif', 'abs', 'hip-flexors', '1. Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.
2. Place your hands behind your head or across your chest.
3. Engage your abs and lift your upper body towards your knees, curling your torso.
