5. Repeat for the desired number of repetitions.', '0277') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0282', 'دراز و نشست روی نیمکت زیرسینه', 'Decline sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. روی نیمکت زیرسینه دراز بکشید، پاها محکم شده و زانوها خم باشد.
۲. دست‌ها را پشت سر یا ضربدری روی سینه بگذارید.
