INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1274', 'شنا سوئدی عمیق', 'Deep push up', 'chest', 'سینه', 'dumbbell', 'دمبل', 'سینه', 'پشت بازو، شانه‌ها', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها کمی بازتر از عرض شانه و بدن در یک خط صاف.
۲. با خم کردن آرنج‌ها سینه را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک بدن نگه دارید.
۳. با فشار کف دست‌ها، دست‌ها را صاف کنید و به وضعیت شروع برگردید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1274.gif', 'chest', 'triceps,deltoids', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.
