INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0324', 'پرس بالاسینه دمبل کف دست رو به هم', 'Dumbbell incline palm-in press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'سینه', 'شانه‌ها، پشت بازو', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت بنشینید و در هر دست یک دمبل با کف دست‌های رو به هم بگیرید.
