INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0351', 'پشت بازو خوابیده دمبل', 'Dumbbell lying triceps extension', 'arms', 'بازو', 'dumbbell', 'دمبل', 'پشت بازو', 'شانه‌ها', '۱. روی نیمکت صاف دراز بکشید و در هر دست یک دمبل با کف دست‌های رو به هم بگیرید.
