INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0380', 'نشر خم دمبل', 'Dumbbell rear lateral raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل با کف دست رو به بدن بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. دست‌ها را با آرنج‌های کمی خم به طرفین بالا ببرید تا موازی زمین شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0380.gif', 'deltoids', 'trapezius,upper-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.
3. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.
4. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
5. Repeat for the desired number of repetitions.', '0380') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0379', 'نشر خم دمبل (با تکیه‌گاه سر)', 'Dumbbell rear lateral raise (support head)', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. دست‌ها را با آرنج‌های کمی خم به طرفین بالا ببرید تا موازی زمین شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0379.gif', 'deltoids', 'trapezius,upper-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.
4. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
5. Repeat for the desired number of repetitions.', '0379') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0381', 'لانج معکوس دمبل', 'Dumbbell rear lunge', 'legs', 'پا', 'dumbbell', 'دمبل', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل بگیرید.
۲. با پای راست یک گام به عقب بردارید و به حالت لانج پایین بروید.
۳. زانوی چپ را خم کنید و بدن را پایین ببرید تا ران چپ موازی زمین شود.
۴. لحظه‌ای مکث کنید، سپس با فشار پاشنه چپ به وضعیت شروع برگردید.
۵. برای طرف دیگر با گام پای چپ به عقب تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0381.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand.
2. Take a step backward with your right foot, lowering your body into a lunge position.
3. Bend your left knee and lower your body until your left thigh is parallel to the ground.
4. Pause for a moment, then push through your left heel to return to the starting position.
5. Repeat on the other side, stepping back with your left foot.', '0381') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0382', 'جلو بازو دست‌برعکس دمبل', 'Dumbbell revers grip biceps curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'جلو بازو', 'ساعد', '۱. صاف بایستید و در هر دست یک دمبل با کف دست رو به پایین و دست‌های کاملاً صاف بگیرید.
۲. بازوها را ثابت نگه دارید و با بازدم، وزنه را با انقباض جلو بازو بالا بیاورید.
۳. وزنه‌ها را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و دمبل‌ها در سطح شانه باشند.
۴. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۵. با دم، دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0382.gif', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.
2. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
3. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale and slowly begin to lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '0382') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1624', 'پرس سینه دست‌برعکس دمبل', 'Dumbbell reverse bench press', 'chest', 'سینه', 'dumbbell', 'دمبل', 'سینه', 'پشت بازو، شانه‌ها', '۱. روی نیمکت صاف دراز بکشید، کف پاها روی زمین و زانوها خم باشد.
۲. در هر دست یک دمبل را از رو با کف دست رو به پاها بگیرید.
۳. دست‌ها را صاف به سمت سقف ببرید و آرنج‌ها را کمی خم نگه دارید.
۴. دمبل‌ها را آرام به سمت سینه پایین بیاورید و اجازه دهید آرنج‌ها به طرفین باز شوند.
۵. لحظه‌ای در پایین مکث کنید، سپس دمبل‌ها را به وضعیت شروع پرس کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1624.gif', 'chest', 'triceps,deltoids', '1. Lie flat on a bench with your feet flat on the ground and your knees bent.
2. Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.
3. Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.
4. Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.
5. Pause for a moment at the bottom, then push the dumbbells back up to the starting position.
6. Repeat for the desired number of repetitions.', '1624') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0383', 'قفسه معکوس دمبل', 'Dumbbell reverse fly', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. دست‌ها را صاف رو به پایین جلوی بدن با کف دست‌های رو به هم دراز کنید.
۴. با آرنج‌های کمی خم، دست‌ها را به طرفین بالا ببرید تا موازی زمین شوند.
۵. لحظه‌ای در بالا مکث کنید، سپس دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0383.gif', 'deltoids', 'trapezius,upper-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Extend your arms straight down in front of you, palms facing each other.
4. Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.
5. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
6. Repeat for the desired number of repetitions.', '0383') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1330', 'زیربغل تک‌دست دست‌برعکس روی نیمکت شیب‌دار دمبل', 'Dumbbell reverse grip incline bench one arm row', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. یک دمبل را کنار نیمکت روی زمین بگذارید.
۳. رو به نیمکت بایستید و پاها را به اندازه عرض شانه باز کنید.
۴. از کمر خم شوید و برای حمایت زانوی چپ و دست چپ را روی نیمکت بگذارید.
۵. دمبل را با دست راست و گرفتن معکوس بردارید.
۶. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۷. دمبل را به سمت سینه بالا بکشید و آرنج را نزدیک بدن نگه دارید.
۸. در اوج حرکت عضلات پشت را منقبض کنید.
۹. دمبل را با کنترل به وضعیت شروع پایین بیاورید.
۱۰. به تعداد تکرار دلخواه انجام دهید.
۱۱. طرف را عوض کنید و تمرین را با دست چپ تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1330.gif', 'upper-back', 'biceps,deltoids', '1. Set up an incline bench at a 45-degree angle.
2. Place a dumbbell on the floor next to the bench.
3. Stand facing the bench with your feet shoulder-width apart.
4. Bend at the waist and place your left knee and left hand on the bench for support.
5. Pick up the dumbbell with your right hand using a reverse grip (palm facing down).
6. Keep your back straight and your core engaged.
7. Pull the dumbbell up towards your chest, keeping your elbow close to your body.
8. Squeeze your back muscles at the top of the movement.
9. Lower the dumbbell back down to the starting position in a controlled manner.
10. Repeat for the desired number of repetitions.
11. Switch sides and repeat the exercise with your left arm.', '1330') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1331', 'زیربغل دو دست دست‌برعکس روی نیمکت شیب‌دار دمبل', 'Dumbbell reverse grip incline bench two arm row', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'بالای پشت', 'جلو بازو، ساعد', '۱. نیمکت شیب‌دار را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی نیمکت بنشینید، سینه به پشتی تکیه داشته باشد و کف پاها روی زمین باشد.
۳. در هر دست یک دمبل را از زیر بگیرید.
۴. به جلو خم شوید و اجازه دهید دست‌ها صاف و کاملاً کشیده آویزان باشند.
۵. دمبل‌ها را به سمت سینه بالا بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در بالا مکث کنید، سپس دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1331.gif', 'upper-back', 'biceps,forearm', '1. Set up an incline bench at a 45-degree angle.
2. Sit on the bench with your chest against the backrest and your feet flat on the ground.
3. Hold a dumbbell in each hand with an underhand grip.
4. Lean forward and let your arms hang straight down, fully extended.
5. Pull the dumbbells up towards your chest, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.
7. Repeat for the desired number of repetitions.', '1331') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2327', 'زیربغل دست‌برعکس دمبل (بانوان)', 'Dumbbell reverse grip row (female)', 'back', 'پشت و زیربغل', 'dumbbell', 'دمبل', 'بالای پشت', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. در هر دست یک دمبل را از رو با کف دست رو به بدن بگیرید.
۳. از کمر به جلو خم شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۴. اجازه دهید دست‌ها صاف و کشیده آویزان باشند و آرنج‌ها کمی خم باشد.
۵. دمبل‌ها را به سمت سینه بالا بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در بالا مکث کنید، سپس دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2327.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart and knees slightly bent.
2. Hold a dumbbell in each hand with an overhand grip, palms facing your body.
3. Bend forward at the waist, keeping your back straight and your core engaged.
4. Let your arms hang straight down, fully extended, with a slight bend in your elbows.
5. Pull the dumbbells up towards your chest, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.
7. Repeat for the desired number of repetitions.', '2327') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0384', 'جلو بازو لاری برعکس دمبل', 'Dumbbell reverse preacher curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'جلو بازو', 'ساعد', '۱. روی نیمکت لاری بنشینید، بازوها روی پد و سینه به تکیه‌گاه باشد.
۲. در هر دست یک دمبل را از زیر با کف دست رو به بالا بگیرید.
۳. بازوها را ثابت نگه دارید و با بازدم دمبل‌ها را با انقباض جلو بازو بالا بیاورید.
۴. دمبل‌ها را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و دمبل‌ها در سطح شانه باشند.
۵. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۶. با دم، دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0384.gif', 'biceps', 'forearm', '1. Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.
2. Hold a dumbbell in each hand with an underhand grip, palms facing up.
3. Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.
4. Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly lower the dumbbells back to the starting position.
7. Repeat for the desired number of repetitions.', '0384') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1675', 'جلو بازو عنکبوتی برعکس دمبل', 'Dumbbell reverse spider curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'جلو بازو', 'ساعد', '۱. صاف بایستید و در هر دست یک دمبل با کف دست رو به بدن و دست‌های کاملاً صاف بگیرید.
۲. بازوها را ثابت نگه دارید و با بازدم، وزنه را با انقباض جلو بازو بالا بیاورید.
۳. دمبل‌ها را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و دمبل‌ها در سطح شانه قرار گیرند.
۴. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۵. با دم، دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1675.gif', 'biceps', 'forearm', '1. Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.
2. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
3. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.
4. Hold the contracted position for a brief pause as you squeeze your biceps.
5. Inhale and slowly begin to lower the dumbbells back to the starting position.
6. Repeat for the desired number of repetitions.', '1675') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0385', 'مچ دست معکوس دمبل', 'Dumbbell reverse wrist curl', 'arms', 'بازو', 'dumbbell', 'دمبل', 'ساعد', 'جلو بازو، بازویی', '۱. روی نیمکت یا صندلی بنشینید و کف پاها را روی زمین بگذارید.
۲. در هر دست یک دمبل را از رو با کف دست رو به پایین بگیرید.
۳. ساعدها را روی ران‌ها بگذارید و اجازه دهید مچ‌ها از لبه آویزان باشند.
۴. مچ‌ها را آرام به سمت بالا خم کنید و دمبل‌ها را به سمت بدن بیاورید.
۵. لحظه‌ای در بالا مکث کنید، سپس دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0385.gif', 'forearm', 'biceps', '1. Sit on a bench or chair with your feet flat on the ground.
2. Hold a dumbbell in each hand with an overhand grip, palms facing down.
3. Rest your forearms on your thighs, allowing your wrists to hang off the edge.
4. Slowly curl your wrists upward, bringing the dumbbells towards your body.
5. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.
6. Repeat for the desired number of repetitions.', '0385') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0386', 'قفسه معکوس چرخشی دمبل', 'Dumbbell rotation reverse fly', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل با کف دست رو به داخل بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف و سینه را بالا نگه دارید.
۳. دست‌ها را با آرنج‌های کمی خم به طرفین بالا ببرید تا موازی زمین شوند.
۴. دست‌ها را بچرخانید تا کف دست‌ها رو به پایین باشد.
۵. دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0386.gif', 'deltoids', 'trapezius,upper-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.
3. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.
4. Rotate your arms so that your palms are facing downwards.
5. Slowly lower your arms back to the starting position.
6. Repeat for the desired number of repetitions.', '0386') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2397', 'پرس اسکات دمبل', 'Dumbbell scott press', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'پشت بازو، سینه', '۱. روی نیمکت بنشینید و در هر دست یک دمبل با کف دست رو به جلو بگیرید.
۲. دمبل‌ها را با آرنج‌های خم و کف دست رو به جلو تا ارتفاع شانه بالا بیاورید.
۳. دمبل‌ها را بالا پرس کنید تا دست‌ها کاملاً صاف شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2397.gif', 'deltoids', 'triceps,chest', '1. Sit on a bench with a dumbbell in each hand, palms facing forward.
2. Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.
3. Press the dumbbells upward until your arms are fully extended.
4. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.
5. Repeat for the desired number of repetitions.', '2397') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0387', 'نشر جلو یک در میان نشسته دمبل', 'Dumbbell seated alternate front raise', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'کول (ذوزنقه)، جلو بازو', '۱. روی نیمکت بنشینید، کمر صاف و کف پاها روی زمین باشد.
۲. در هر دست یک دمبل با کف دست رو به بدن بگیرید و دست‌ها را صاف کنار بدن آویزان کنید.
۳. با دست‌های صاف، یک دمبل را جلوی بدن بالا بیاورید تا موازی زمین شود.
۴. لحظه‌ای در بالا مکث کنید، سپس دمبل را آرام به وضعیت شروع پایین بیاورید.
۵. با دست دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه دست‌ها را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0387.gif', 'deltoids', 'trapezius,biceps', '1. Sit on a bench with your back straight and feet flat on the ground.
2. Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.
3. Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.
4. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.
5. Repeat with the other arm.
6. Alternate between arms for the desired number of repetitions.', '0387') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1676', 'جلو بازو چکشی یک در میان نشسته روی توپ تعادلی دمبل', 'Dumbbell seated alternate hammer curl on exercise ball', 'arms', 'بازو', 'dumbbell', 'دمبل', 'جلو بازو', 'ساعد', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و کمر صاف باشد.
۲. در هر دست یک دمبل با کف دست رو به بدن و دست‌های کاملاً صاف بگیرید.
۳. بازوها را ثابت نگه دارید و با بازدم یک دمبل را به سمت شانه بالا بیاورید و کف دست را رو به بدن نگه دارید.
۴. دمبل را تا جایی بالا بیاورید که جلو بازو کاملاً منقبض شود و دمبل در سطح شانه باشد.
۵. وضعیت انقباض را لحظه‌ای نگه دارید و جلو بازو را بفشارید.
۶. با دم، دمبل را آرام به وضعیت شروع پایین بیاورید.
۷. حرکت را با دست مقابل تکرار کنید.
۸. به تعداد تکرار دلخواه، دست‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1676.gif', 'biceps', 'forearm', '1. Sit on an exercise ball with your feet flat on the ground and your back straight.
2. Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.
3. Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.
4. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.
5. Hold the contracted position for a brief pause as you squeeze your biceps.
6. Inhale and slowly lower the dumbbell back to the starting position.
7. Repeat the movement with the opposite arm.
8. Continue alternating arms for the desired number of repetitions.', '1676') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0388', 'پرس یک در میان نشسته دمبل', 'Dumbbell seated alternate press', 'shoulders', 'سرشانه', 'dumbbell', 'دمبل', 'سرشانه', 'پشت بازو، سینه', '۱. روی نیمکت بنشینید و در هر دست یک دمبل با کف دست رو به جلو بگیرید.
۲. دمبل‌ها را با آرنج‌های خم و کف دست رو به جلو تا ارتفاع شانه بالا بیاورید.
۳. یک دمبل را بالای سر پرس کنید و دست را کاملاً صاف کنید.
۴. دمبل را تا ارتفاع شانه پایین بیاورید.
